#include <omp.h>
#include <vector>
#include <stdexcept>
#include <cstddef>

void axpy(double alpha, std::vector<double> const& x, std::vector<double> const& y, std::vector<double> &z) {
    if (x.size() != y.size()) {
        throw std::invalid_argument("axpy: x and y must have the same size");
    }

    const std::size_t n = x.size();
    if (z.size() != n) {
        z.resize(n);
    }

    #pragma omp parallel for default(none) shared(alpha, x, y, z, n) schedule(static)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(n); ++i) {
        const std::size_t idx = static_cast<std::size_t>(i);
        z[idx] = alpha * x[idx] + y[idx];
    }
}
